#!/usr/bin/env python3
"""Regenerates the generated parts of serpent/PROOF.bend, in place.

  python3 gen/proof.py           rewrite the regions between the lines
                                 "# BEGIN GENERATED by gen/proof.py: <name>"
                                 and "# END GENERATED: <name>"
  python3 gen/proof.py --check   only check that they are up to date

Two regions:
  "bits"     Serpent's rotations undone, proved by splitting a word into
             its 32 bits (a deep pattern then {==});
  "serpent"  each S-box and its inverse on all 16 inputs, the S-box layer
             lifted one bit position at a time, and the linear
             transformation undone step by step;
Everything outside the regions is written by hand (the vector laws'
proofs are gen/vectors.py's).
"""
import os, re, sys

HERE = os.path.dirname(os.path.abspath(__file__))
PKG = os.path.join(HERE, "..")


def word(prefix, n=32):
    s = "WNil{}"
    for i in reversed(range(n)):
        s = "WCon{%s%d, %s}" % (prefix, i, s)
    return s


def u32(prefix):
    return "U32{%s}" % word(prefix)


# ---------------------------------------------------------------- bits

def bits_region():
    out = ["# Serpent's rotations on bits undone, for every word: computed on its 32 bits"]
    for a, b in [(19, 13), (13, 19), (29, 3), (3, 29), (25, 7), (7, 25),
                 (27, 5), (5, 27), (10, 22), (22, 10)]:
        out.append("def rot_%d_%d(x: U32) -> {x == L.lc.rotl%d.bits(L.lc.rotl%d.bits(x)) : U32}:\n"
                   "  match x:\n    case %s:\n      {==}" % (a, b, a, b, u32("a")))
    return "\n\n".join(out) + "\n"


# ---------------------------------------------------------------- serpent

def serpent_nib():
    out = ["# the S-box and its inverse undo each other on every 4-bit input\n"]
    bools = ["True{}", "False{}"]
    for bx in range(8):
        for inv in (True, False):
            iv = "True{}" if inv else "False{}"
            nv = "False{}" if inv else "True{}"
            name = "sp_nib_%d_%s" % (bx, "t" if inv else "f")
            o = "P.sp.nib(P.LcSp%d{}, %s, n)" % (bx, iv)
            out.append("def %s(+n: P.LcSpNib) -> {n == P.sp.nib(P.LcSp%d{}, %s, P.LcSpNib{P.sp.na(%s), P.sp.nb(%s), P.sp.nc(%s), P.sp.nd(%s)}) : P.LcSpNib}:" % (name, bx, nv, o, o, o, o))
            out.append("  match n:")
            out.append("    case P.LcSpNib{a, b, c, d}:")
            out.append("      match a b c d:")
            for a in bools:
                for b in bools:
                    for c in bools:
                        for d in bools:
                            out.append("        case %s %s %s %s:" % (a, b, c, d))
                            out.append("          {==}")
            out.append("")
    out.append("def sp_nib_inv(bx: P.LcSpBox, inv: Bool, +n: P.LcSpNib) -> {n == P.sp.nib(bx, Bool.not(inv), P.LcSpNib{P.sp.na(P.sp.nib(bx, inv, n)), P.sp.nb(P.sp.nib(bx, inv, n)), P.sp.nc(P.sp.nib(bx, inv, n)), P.sp.nd(P.sp.nib(bx, inv, n))}) : P.LcSpNib}:")
    out.append("  match bx:")
    for bx in range(8):
        out.append("    case P.LcSp%d{}:" % bx)
        out.append("      match inv:")
        out.append("        case True{}:")
        out.append("          sp_nib_%d_t(n)" % bx)
        out.append("        case False{}:")
        out.append("          sp_nib_%d_f(n)" % bx)
    out.append("")
    return "\n".join(out)


def serpent_layer():
    R = "P.sp.layer(bx, inv, p, P.LcSpQ{t0, t1, t2, t3})"
    RP = "P.sp.layer(bx, Bool.not(inv), p, P.LcSpQ{P.sp.qa(p, %s), P.sp.qb(p, %s), P.sp.qc(p, %s), P.sp.qd(p, %s)})" % (R, R, R, R)
    LHS = "P.LcSpQ{WCon{x0, t0}, WCon{x1, t1}, WCon{x2, t2}, WCon{x3, t3}}"
    R32 = "P.sp.layer(bx, inv, 32n, P.LcSpQ{w0, w1, w2, w3})"
    RR32 = "P.sp.layer(bx, Bool.not(inv), 32n, P.LcSpQ{P.sp.qa(32n, %s), P.sp.qb(32n, %s), P.sp.qc(32n, %s), P.sp.qd(32n, %s)})" % (R32, R32, R32, R32)
    return """
# a layer's input rebuilt from its fields gives the same layer
def sp_eta(+bx: P.LcSpBox, +inv: Bool, -p: Nat, z: P.LcSpQ<p>) -> {P.sp.layer(bx, inv, p, z) == P.sp.layer(bx, inv, p, P.LcSpQ{P.sp.qa(p, z), P.sp.qb(p, z), P.sp.qc(p, z), P.sp.qd(p, z)}) : P.LcSpQ<p>}:
  match z:
    case P.LcSpQ{a, b, c, d}:
      {==}

# an S-box layer and its inverse undo each other on four m-bit words
def sp_layer_inv(+bx: P.LcSpBox, +inv: Bool, m: Nat, +q: P.LcSpQ<m>) -> {q == P.sp.layer(bx, Bool.not(inv), m, P.sp.layer(bx, inv, m, q)) : P.LcSpQ<m>}:
  match m:
    case 0n:
      {==}
    case 1n+(+p):
      match q:
        case P.LcSpQ{WCon{+x0, +t0}, WCon{+x1, +t1}, WCon{+x2, +t2}, WCon{+x3, +t3}}:
          %sp_nib_inv(bx, inv, P.LcSpNib{x0, x1, x2, x3}) : {@LHS == P.LcSpQ{WCon{P.sp.na(_), P.sp.qa(p, @RP)}, WCon{P.sp.nb(_), P.sp.qb(p, @RP)}, WCon{P.sp.nc(_), P.sp.qc(p, @RP)}, WCon{P.sp.nd(_), P.sp.qd(p, @RP)}} : P.LcSpQ<1n+p>}
          %Equal.trans(P.LcSpQ<p>, P.LcSpQ{t0, t1, t2, t3}, P.sp.layer(bx, Bool.not(inv), p, @R), @RP, sp_layer_inv(bx, inv, p, P.LcSpQ{t0, t1, t2, t3}), sp_eta(bx, Bool.not(inv), p, @R)) : {@LHS == P.LcSpQ{WCon{x0, P.sp.qa(p, _)}, WCon{x1, P.sp.qb(p, _)}, WCon{x2, P.sp.qc(p, _)}, WCon{x3, P.sp.qd(p, _)}} : P.LcSpQ<1n+p>}
          {==}

# an S-box step and its inverse undo each other on the state
def sp_sop_inv(+bx: P.LcSpBox, +inv: Bool, s: M.CmBlock) -> {s == P.sp.sop(bx, Bool.not(inv), P.sp.sop(bx, inv, s)) : M.CmBlock}:
  match s:
    case M.CmBlock{U32{+w0}, U32{+w1}, U32{+w2}, U32{+w3}}:
      %Equal.trans(P.LcSpQ<32n>, P.LcSpQ{w0, w1, w2, w3}, P.sp.layer(bx, Bool.not(inv), 32n, @R32), @RR32, sp_layer_inv(bx, inv, 32n, P.LcSpQ{w0, w1, w2, w3}), sp_eta(bx, Bool.not(inv), 32n, @R32)) : {M.CmBlock{U32{w0}, U32{w1}, U32{w2}, U32{w3}} == M.CmBlock{U32{P.sp.qa(32n, _)}, U32{P.sp.qb(32n, _)}, U32{P.sp.qc(32n, _)}, U32{P.sp.qd(32n, _)}} : M.CmBlock}
      {==}
""".replace("@RR32", RR32).replace("@R32", R32).replace("@LHS", LHS).replace("@RP", RP).replace("@R", R)


def serpent_lt():
    out = ["\n# the linear transformation's steps, each undone"]

    def lemma(name, outer, inner, rewrites):
        s = "def %s(s: M.CmBlock) -> {s == P.sp.%s(P.sp.%s(s)) : M.CmBlock}:\n  match s:\n    case M.CmBlock{+x0, +x1, +x2, +x3}:\n" % (name, outer, inner)
        for lem, arg, idx, rest in rewrites:
            h = ["x0", "x1", "x2", "x3"]
            for j, r in rest.items():
                h[j] = r
            h[idx] = "_"
            s += "      %%%s(%s) : {M.CmBlock{x0, x1, x2, x3} == M.CmBlock{%s} : M.CmBlock}\n" % (lem, arg, ", ".join(h))
        s += "      {==}\n"
        out.append(s)

    lemma("sp_lt1", "ilt1", "lt1", [("rot_19_13", "x0", 0, {})])
    lemma("sp_lt1d", "lt1", "ilt1", [("rot_13_19", "x0", 0, {})])
    lemma("sp_lt2", "ilt2", "lt2", [("rot_29_3", "x2", 2, {})])
    lemma("sp_lt2d", "lt2", "ilt2", [("rot_3_29", "x2", 2, {})])
    lemma("sp_lt3", "lt3", "lt3", [("CoreL.u32_xor_cancel", "x1, U32.xor(x0, x2)", 1, {})])
    lemma("sp_lt4", "lt4", "lt4", [("CoreL.u32_xor_cancel", "x3, U32.xor(x2, U32.shln(x0, 3n))", 3, {})])
    lemma("sp_lt5", "ilt5", "lt5", [("CoreL.rotl31_rotl1", "x1", 1, {3: "L.lc.rotl25.bits(L.lc.rotl7.bits(x3))"}), ("rot_25_7", "x3", 3, {})])
    lemma("sp_lt5d", "lt5", "ilt5", [("CoreL.rotl1_rotl31", "x1", 1, {3: "L.lc.rotl7.bits(L.lc.rotl25.bits(x3))"}), ("rot_7_25", "x3", 3, {})])
    lemma("sp_lt6", "lt6", "lt6", [("CoreL.u32_xor_cancel", "x0, U32.xor(x1, x3)", 0, {})])
    lemma("sp_lt7", "lt7", "lt7", [("CoreL.u32_xor_cancel", "x2, U32.xor(x3, U32.shln(x1, 7n))", 2, {})])
    lemma("sp_lt8", "ilt8", "lt8", [("rot_27_5", "x0", 0, {2: "L.lc.rotl10.bits(L.lc.rotl22.bits(x2))"}), ("rot_10_22", "x2", 2, {})])
    lemma("sp_lt8d", "lt8", "ilt8", [("rot_5_27", "x0", 0, {2: "L.lc.rotl22.bits(L.lc.rotl10.bits(x2))"}), ("rot_22_10", "x2", 2, {})])

    def nest(fs, inner):
        s = inner
        for f in reversed(fs):
            s = "P.sp.%s(%s)" % (f, s)
        return s

    fwd = ["lt8", "lt7", "lt6", "lt5", "lt4", "lt3", "lt2", "lt1"]
    inv = ["ilt1", "ilt2", "lt3", "lt4", "ilt5", "lt6", "lt7", "ilt8"]
    s = "def sp_lt_inv(+s: M.CmBlock) -> {s == P.sp.ilt(P.sp.lt(s)) : M.CmBlock}:\n"
    lem = ["sp_lt8", "sp_lt7", "sp_lt6", "sp_lt5", "sp_lt4", "sp_lt3", "sp_lt2", "sp_lt1"]
    for i in range(7):
        s += "  %%%s(%s) : {s == %s : M.CmBlock}\n" % (lem[i], nest(fwd[i + 1:], "s"), nest(inv[:7 - i], "_"))
    s += "  sp_lt1(s)\n"
    out.append(s)
    s = "def sp_lt_invd(+s: M.CmBlock) -> {s == P.sp.lt(P.sp.ilt(s)) : M.CmBlock}:\n"
    lemd = ["sp_lt1d", "sp_lt2d", "sp_lt3", "sp_lt4", "sp_lt5d", "sp_lt6", "sp_lt7", "sp_lt8d"]
    for i in range(7):
        s += "  %%%s(%s) : {s == %s : M.CmBlock}\n" % (lemd[i], nest(inv[i + 1:], "s"), nest(fwd[:7 - i], "_"))
    s += "  sp_lt8d(s)\n"
    out.append(s)
    return "\n".join(out)


def serpent_region():
    return serpent_nib() + serpent_layer() + serpent_lt()


REGIONS = {"bits": bits_region, "serpent": serpent_region}


def main():
    path = os.path.join(PKG, "PROOF.bend")
    with open(path, encoding="utf-8", newline="") as f:
        src = f.read()
    new = src
    for name, body in REGIONS.items():
        begin = "# BEGIN GENERATED by gen/proof.py: %s\n" % name
        end = "# END GENERATED: %s\n" % name
        i = new.index(begin) + len(begin)
        j = new.index(end, i)
        new = new[:i] + body() + new[j:]
    if "--check" in sys.argv[1:]:
        if new != src:
            print("PROOF.bend differs from what gen/proof.py generates")
            sys.exit(1)
        print("PROOF.bend is up to date")
        return
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(new)


main()
